// Build src/catalog-data.js from the committed official gzip. Generated file is gitignored.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const srcDir = path.join(here, '../src');
const gzPath = path.join(srcDir, 'catalog.json.gz');
const outPath = path.join(srcDir, 'catalog-data.js');
const buf = fs.readFileSync(gzPath);
const b64 = buf.toString('base64');
const banner = '// Generated by scripts/embed-catalog.mjs from catalog.json.gz. Do not edit.\n';
fs.writeFileSync(outPath, banner + 'export const CATALOG_GZ_B64 = "' + b64 + '";\n');
console.log('wrote', path.relative(process.cwd(), outPath), 'from', buf.length, 'byte gzip');
